# Surah Al-Anfal (chapter 8) — part 5: ayat 39-48 (IDs 1199-1208)
SURAH = 8

ENTRIES = {
1199: (
"اور — ان سے — اس وقت تک — لڑو — جب تک — فتنہ باقی نہ رہے — اور — دین — سب اللہ کے لیے — ہو جائے — پس — اگر — وہ — باز آ جائیں — تو — بے شک — اللہ — ان کے اعمال — دیکھ رہا ہے",
"""۱۔ قتال — فتنہ ختم اور دینِ خالص اللہ کے لیے — ہونے تک۔
۲۔ ’’وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَۃٌ وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ فَإِنِ انتَهَوْا فَإِنَّ اللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ‘‘ — اور — ان سے — اس وقت تک — لڑو — جب تک — فتنہ باقی نہ رہے — اور — دین — سب اللہ کے لیے — ہو جائے — پس — اگر — وہ — باز آ جائیں — تو — بے شک — اللہ — ان کے اعمال — دیکھ رہا ہے — یعنی قتال — شرک و ظلم کے خاتمے — کے لیے جائز ہے — فتح کے بعد بھی — اللہ — سب دیکھ رہا ہے۔
۳۔ عملی سبق: جنگ — صرف اللہ کی خوشنودی کے لیے؛ لالچ کے لیے نہیں۔"""
),
1200: (
"اور — اگر — وہ — منہ موڑیں — تو — جان لو — کہ — اللہ — تمہارا — کارساز ہے — وہ — بہترین کارساز — اور بہترین — مددگار ہے",
"""۱۔ اللہ — بہترین ولی اور ناصر۔
۲۔ ’’وَإِن تَوَلَّوْا فَاعْلَمُوا أَنَّ اللَّهَ مَوْلَاكُمْ نِعْمَ الْمَوْلَىٰ وَنِعْمَ النَّصِيرُ‘‘ — اور — اگر — وہ — منہ موڑیں — تو — جان لو — کہ — اللہ — تمہارا — کارساز ہے — وہ — بہترین کارساز — اور بہترین — مددگار ہے — یعنی جب دشمن منہ موڑے — اللہ — ہماری کافی ہے۔
۳۔ عملی سبق: اللہ — بہترین مددگار ہے؛ اسی پر بھروسہ کرو۔"""
),
1201: (
"اور — جان لو — کہ — جو کچھ تم — مالِ غنیمت — میں سے پاتے ہو — اس کا پانچواں حصہ — اللہ کے لیے — اور رسولؐ — کے لیے — اور — قریبی رشتہ داروں — یتیموں — مسکینوں — اور مسافروں — کے لیے ہے — اگر — تم — اللہ پر — اور — اس — پر — ایمان رکھتے ہو — جو — ہم نے — اپنے بندے پر — بدر کے دن — اتارا — جب — دو جماعتیں — ملیں — اور — اللہ — ہر — چیز پر — قادر ہے",
"""۱۔ مالِ غنیمت میں خمس — یعنی پانچواں حصہ — اللہ اور رسولؐ کا حق۔
۲۔ ’’وَاعْلَمُوا أَنَّمَا غَنِمْتُم مِّن شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنُ السَّبِيلِ إِن كُنتُمْ آمَنتُم بِاللَّهِ وَمَا أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ الْفُرْقَانِ يَوْمَ الْتَقَى الْجَمْعَانِ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — اور — جان لو — کہ — جو کچھ تم — مالِ غنیمت — میں سے پاتے ہو — اس کا پانچواں حصہ — اللہ کے لیے — اور رسولؐ — کے لیے — اور — قریبی رشتہ داروں — یتیموں — مسکینوں — اور مسافروں — کے لیے ہے — اگر — تم — اللہ پر — اور — اس — پر — ایمان رکھتے ہو — جو — ہم نے — اپنے بندے پر — بدر کے دن — اتارا — جب — دو جماعتیں — ملیں — اور — اللہ — ہر — چیز پر — قادر ہے — یعنی غنیمت میں — خمس — اللہ اور رسولؐ اور — اہلِ بیتؑ و ضرورتیں دینے والوں کا — حق ہے۔
۳۔ شیعہ تفسیر: خمس — اللہ، رسولؐ، ذی القربیٰ (اہلِ بیتؑ), یتیموں، مسکینوں اور مسافروں — میں تقسیم کیا جاتا ہے۔
۴۔ عملی سبق: خمس ادا کرو؛ یہ — تمہارے مال کی پاکیزگی — کا سبب ہے۔"""
),
1202: (
"یاد کرو — جب — تم — قریب کی وادی میں تھے — اور وہ — دور کی وادی میں — اور — قافلہ — تمہارے سے نیچے تھا — اور — اگر — تم — آپس میں وعدہ کرتے — تو — تم — اختلاف کر جاتے — لیکن — اللہ — چاہتا تھا — ایک امر — پورا کرے — جو — ہونا تھا — تاکہ — جس کو — ہلاک ہونا ہے — وہ — دلیل سے ہلاک ہو — اور — جس — کو — زندہ رہنا ہے — وہ — دلیل سے زندہ رہے — اور — بے شک — اللہ — سننے والا جاننے والا ہے",
"""۱۔ بدر کا جغرافیہ — اور اللہ کی تدبیر۔
۲۔ ’’إِذْ أَنتُم بِالْعُدْوَۃِ الدُّنْيَا وَهُم بِالْعُدْوَۃِ الْقُصْوَىٰ وَالرَّكْبُ أَسْفَلَ مِنكُمْ وَلَوْ تَوَاعَدتُّمْ لَاخْتَلَفْتُمْ فِي الْمِيعَادِ وَلَٰكِن لِّيَقْضِيَ اللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَن بَيِّنَۃٍ وَيَحْيَىٰ مَنْ حَيَّ عَن بَيِّنَۃٍ وَإِنَّ اللَّهَ لَسَمِيعٌ عَلِيمٌ‘‘ — یاد کرو — جب — تم — قریب کی وادی میں تھے — اور وہ — دور کی وادی میں — اور — قافلہ — تمہارے سے نیچے تھا — اور — اگر — تم — آپس میں وعدہ کرتے — تو — تم — اختلاف کر جاتے — لیکن — اللہ — چاہتا تھا — ایک امر — پورا کرے — جو — ہونا تھا — تاکہ — جس کو — ہلاک ہونا ہے — وہ — دلیل سے ہلاک ہو — اور — جس — کو — زندہ رہنا ہے — وہ — دلیل سے زندہ رہے — اور — بے شک — اللہ — سننے والا جاننے والا ہے — یعنی اللہ نے — ہر حال میں — حق و باطل کا — فیصلہ — واضح کر دیا۔
۳۔ عملی سبق: اللہ کے فیصلے — انسانی منصوبوں سے — بالاتر ہیں۔"""
),
1203: (
"یاد کرو — جب — اللہ — تمہیں — انہیں — خواب میں — تھوڑا دکھاتا ہے — اور — اگر — وہ تمہیں — زیادہ دکھاتا — تو — تم — کمزور پڑ جاتے — اور — اس — معاملے میں — تنازع کرتے — لیکن — اللہ نے — محفوظ رکھا — بے شک — وہ — سینوں کی — باتوں کو — جاننے والا ہے",
"""۱۔ خواب میں دشمن کی قلت — اللہ کی مہربانی۔
۲۔ ’’إِذْ يُرِيكَهُمُ اللَّهُ فِي مَنَامِكَ قَلِيلًا وَلَوْ أَرَاكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَازَعْتُمْ فِي الْأَمْرِ وَلَٰكِنَّ اللَّهَ سَلَّمَ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ‘‘ — یاد کرو — جب — اللہ — تمہیں — انہیں — خواب میں — تھوڑا دکھاتا ہے — اور — اگر — وہ تمہیں — زیادہ دکھاتا — تو — تم — کمزور پڑ جاتے — اور — اس — معاملے میں — تنازع کرتے — لیکن — اللہ نے — محفوظ رکھا — بے شک — وہ — سینوں کی — باتوں کو — جاننے والا ہے — یعنی اللہ — کامیاب ہونے کے لیے — خواب میں دشمن کو — کم دکھاتا ہے۔
۳۔ عملی سبق: اللہ — ہر سینے کی بات — جانتا ہے۔"""
),
1204: (
"اور — یاد کرو — جب — وہ تمہیں — ملاقات کے وقت — تمہاری آنکھوں میں — تھوڑا دکھاتا ہے — اور — تمہیں — ان کی آنکھوں میں — تھوڑا دکھاتا ہے — تاکہ — اللہ — ایک امر — پورا کرے — جو — ہونا تھا — اور — تمام — معاملات — اللہ کی طرف — لوٹائے جاتے ہیں",
"""۱۔ دونوں طرف — دشمن کو تھوڑا دیکھنا — اللہ کی تدبیر۔
۲۔ ’’وَإِذْ يُرِيكُمُوهُمْ إِذِ الْتَقَيْتُمْ فِي أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِي أَعْيُنِهِمْ لِيَقْضِيَ اللَّهُ أَمْرًا كَانَ مَفْعُولًا وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ‘‘ — اور — یاد کرو — جب — وہ تمہیں — ملاقات کے وقت — تمہاری آنکھوں میں — تھوڑا دکھاتا ہے — اور — تمہیں — ان کی آنکھوں میں — تھوڑا دکھاتا ہے — تاکہ — اللہ — ایک امر — پورا کرے — جو — ہونا تھا — اور — تمام — معاملات — اللہ کی طرف — لوٹائے جاتے ہیں — یعنی اللہ — دونوں طرف کے دلوں میں — خوف ڈال کر — بدر کا فیصلہ کرواتا ہے۔
۳۔ عملی سبق: اللہ کے فیصلے — ظاہری حالات سے — اوپر ہوتے ہیں۔"""
),
1205: (
"اے ایمان والو — جب — تم — کسی گروہ — سے — ملو — تو ثابت قدم رہو — اور — اللہ کو — بہت زیادہ — یاد کرو — شاید — تم — فلاح پا جاؤ",
"""۱۔ جنگ میں ثابت قدمی — اور ذکر کثیر۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا لَقِيتُمْ فِئَۃً فَاثْبُتُوا وَاذْكُرُوا اللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ‘‘ — اے ایمان والو — جب — تم — کسی گروہ — سے — ملو — تو ثابت قدم رہو — اور — اللہ کو — بہت زیادہ — یاد کرو — شاید — تم — فلاح پا جاؤ — یعنی جنگ میں — ثابت قدمی — اور ذکرِ الٰہی — کامیابی کی کلید — ہے۔
۳۔ عملی سبق: جنگ — صرف ثابت قدمی اور اللہ کے ذکر — سے — جیتی جا سکتی ہے۔"""
),
1206: (
"اور — اللہ اور اس کے رسولؐ — کی اطاعت کرو — اور — آپس میں — جھگڑا مت کرو — ورنہ — تم — کمزور پڑ جاؤ گے — اور تمہاری — ہوا (شوہرت) — ختم ہو جائے گی — اور صبر کرو — بے شک — اللہ — صبر کرنے والوں کے ساتھ ہے",
"""۱۔ اتحاد اور صبر — کامیابی کی شرط۔
۲۔ ’’وَأَطِيعُوا اللَّهَ وَرَسُولَهُ وَلَا تَنَازَعُوا فَتَفْشَلُوا وَتَذْهَبَ رِيحُكُمْ وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ‘‘ — اور — اللہ اور اس کے رسولؐ — کی اطاعت کرو — اور — آپس میں — جھگڑا مت کرو — ورنہ — تم — کمزور پڑ جاؤ گے — اور تمہاری — ہوا (شوہرت) — ختم ہو جائے گی — اور صبر کرو — بے شک — اللہ — صبر کرنے والوں کے ساتھ ہے — یعنی مؤمنوں کا اتحاد — اور صبر — ہی کامیابی کی ضمانت ہے۔
۳۔ عملی سبق: آپس کا جھگڑا — مؤمنوں کی سب سے بڑی کمزوری ہے۔"""
),
1207: (
"اور — ان کی طرح مت بنو — جو — اپنے گھروں سے — تکبر — اور دکھاوے — کے لیے — نکلے — اور — اللہ کے راستے سے — روکتے ہیں — اور — اللہ — ان کے اعمال — پر محیط ہے",
"""۱۔ کفارِ قریش — آرائش اور دکھاوے کے لیے — بدر آئے۔
۲۔ ’’وَلَا تَكُونُوا كَالَّذِينَ خَرَجُوا مِن دِيَارِهِم بَطَرًا وَرِئَاءَ النَّاسِ وَيَصُدُّونَ عَن سَبِيلِ اللَّهِ وَاللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ‘‘ — اور — ان کی طرح مت بنو — جو — اپنے گھروں سے — تکبر — اور دکھاوے — کے لیے — نکلے — اور — اللہ کے راستے سے — روکتے ہیں — اور — اللہ — ان کے اعمال — پر محیط ہے — یعنی کفارِ قریش — آرائش و ریا کے لیے — بدر آئے — مگر — اللہ — ان کی ساری چالیں — دیکھ رہا تھا۔
۳۔ عملی سبق: نیت میں اخلاص رکھو؛ تکبر اور ریا — تباہ کن ہے۔"""
),
1208: (
"اور — یاد کرو — جب — شیطان نے — ان کے اعمال — ان کے سامنے سجائے — اور کہا — آج — تم پر — کوئی غالب نہیں — اور — میں — تمہارے پڑوسی ہوں — پس — جب — دونوں جماعتیں — آمنے سامنے ہوئیں — وہ — اپنی ایڑیوں — پر — پیچھے — ہٹ گیا — اور کہا — میں — تم سے — بری ہوں — بے شک — میں — وہ دیکھ رہا ہوں جو — تم نہیں دیکھتے — بے شک — میں — اللہ سے ڈرتا ہوں — اور — اللہ — سخت عذاب دینے والا ہے",
"""۱۔ شیطان — کامیابی کا وعدہ کر کے — آخر — فرار ہو جاتا ہے۔
۲۔ ’’وَإِذْ زَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ الْيَوْمَ مِنَ النَّاسِ وَإِنِّي جَارٌ لَّكُمْ فَلَمَّا تَرَاءَتِ الْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّي بَرِيءٌ مِّنكُمْ إِنِّي أَرَىٰ مَا لَا تَرَوْنَ إِنِّي أَخَافُ اللَّهَ وَاللَّهُ شَدِيدُ الْعِقَابِ‘‘ — اور — یاد کرو — جب — شیطان نے — ان کے اعمال — ان کے سامنے سجائے — اور کہا — آج — تم پر — کوئی غالب نہیں — اور — میں — تمہارے پڑوسی ہوں — پس — جب — دونوں جماعتیں — آمنے سامنے ہوئیں — وہ — اپنی ایڑیوں — پر — پیچھے — ہٹ گیا — اور کہا — میں — تم سے — بری ہوں — بے شک — میں — وہ دیکھ رہا ہوں جو — تم نہیں دیکھتے — بے شک — میں — اللہ سے ڈرتا ہوں — اور — اللہ — سخت عذاب دینے والا ہے — یعنی شیطان — مشرکوں کو کامیابی کا دھوکہ دے کر — خود — بھاگ جاتا ہے۔
۳۔ عملی سبق: شیطان کی مدد پر — کبھی — بھروسہ نہ کرو۔"""
),
}
